import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Determine aspect ratio from atlas region (default to full texture if unknown)
  const atlasRect = config.atlasRegion?.sourceRect ?? { x: 0, y: 0, w: 512, h: 320 };
  const aspect = atlasRect.w / atlasRect.h;

  // Plane geometry sized to aspect ratio, height = 1 unit
  const height = 1;
  const width = aspect * height;
  const geometry = new PlaneGeometry(width, height);

  // Basic material (will receive texture asynchronously)
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;
  material.depthWrite = false;

  // Create mesh
  const mesh = new Mesh(geometry, material);
  mesh.frustumCulled = false; // ensure visibility even if off‑center

  // Billboard to camera on each render
  mesh.onBeforeRender = (_, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  root.add(mesh);

  // Load texture asynchronously
  let textureResource = null;
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texPromise.then((tex) => {
    textureResource = tex;
    // Apply atlas UV offset / repeat if needed
    const img = tex.image;
    if (img && (atlasRect.w !== img.width || atlasRect.h !== img.height)) {
      const repeatX = atlasRect.w / img.width;
      const repeatY = atlasRect.h / img.height;
      const offsetX = atlasRect.x / img.width;
      const offsetY = 1 - (atlasRect.y + atlasRect.h) / img.height; // flip Y for WebGL
      tex.repeat.set(repeatX, repeatY);
      tex.offset.set(offsetX, offsetY);
    }
    // Connect texture to material via node system
    material.map = texture(tex);
    material.needsUpdate = true;
    tex.needsUpdate = true;
  });

  // Apply any cinematic primitives listed in config
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params ?? {});
        primitiveInstances.push(instance);
        // If a trigger is defined, we trust the primitive to bind it internally.
      }
    }
  }

  // Handlers placeholder (no interactions defined)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose texture if loaded
    if (textureResource) {
      textureResource.dispose();
    }

    // Cancel any GSAP timelines (none expected but safe)
    gsap.globalTimeline.clear();

    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }
  };

  return root;
}
